namespace Tahona.BakeryPOS.Domain.Common;

/// <summary>
/// Base of persistent entities: a UUID v7 id generated by the application, audit columns,
/// optimistic concurrency (a row version) and soft delete for master data.
/// The audit columns are filled by the DbContext; the domain does not touch them.
/// </summary>
public abstract class AuditableEntity
{
    public Guid Id { get; protected init; } = Guid.CreateVersion7();

    public DateTime CreatedAt { get; set; }
    public string CreatedBy { get; set; } = string.Empty;
    public DateTime? ModifiedAt { get; set; }
    public string? ModifiedBy { get; set; }
    public byte[] RowVersion { get; set; } = [];
    public DateTime? DeletedAt { get; set; }
    public string? DeletedBy { get; set; }
    public bool IsDeleted => DeletedAt.HasValue;

    private readonly List<IDomainEvent> _domainEvents = [];
    public IReadOnlyList<IDomainEvent> DomainEvents => _domainEvents.AsReadOnly();

    protected void AddDomainEvent(IDomainEvent domainEvent) => _domainEvents.Add(domainEvent);
    public void ClearDomainEvents() => _domainEvents.Clear();
}
